### What happened

A `null` guard and the entire branch it protects were **removed from the production bundle** by `next build` on `16.3.0-preview.9`. The same source, built with `16.2.10`, keeps the branch.

This shipped to production and caused a sustained outage: the unguarded read reached `existing.schemaVersion` on `null`, the API route returned 500, and our Durable Object retried the webhook, so a single affected user's hand looped. 640+ errors over ~50 minutes from **4 real users** before we identified it.

### Source

```ts
async function readDoc<T>({ container, id, partitionKey }): Promise<T | null> {
  try {
    const { resource } = await container.item(id, partitionKey).read<T>()
    return resource ?? null
  } catch (error) {
    if (isNotFound(error)) return null
    throw error
  }
}

async function readCashGameStatsDoc(userId, mode, container): Promise<Doc | null> {
  return readDoc<Doc>({ container, id: cashGameStatsId(mode), partitionKey: userId })
}

async function ensureCashGameStatsDoc({ container, mode, now, userId }): Promise<Doc> {
  const existing = await readCashGameStatsDoc(userId, mode, container)
  if (!existing) {                                   // <-- this whole branch disappears
    const created = emptyStatsDoc({ userId, mode, now })
    try {
      await container.items.create(created)
    } catch (error) {
      if (isConflict(error)) {
        return (await readCashGameStatsDoc(userId, mode, container)) ?? created
      }
      throw error
    }
    return created
  }
  if ((existing.schemaVersion ?? 1) >= CASH_GAME_STATS_SCHEMA_VERSION) return existing
  return migrateCashGameStatsDoc({ container, doc: existing, now })
}
```

