### Link to the code that reproduces this issue

The self-contained Node reproducer below exercises Next's compiled App Router
client. It does not require an application:

```js
const Module = require('node:module')

async function main() {
process.env.NODE_ENV = 'production'
process.env.NEXT_DEPLOYMENT_ID = 'old-build'

let decodeStarted = false
const originalLoad = Module._load
Module._load = function (request, parent, isMain) {
  if (request === 'react-server-dom-webpack/client') {
    return {
      createFromFetch() {
        decodeStarted = true
        return Promise.resolve({ b: 'new-build', f: [] })
      },
      createFromReadableStream() {
        decodeStarted = true
        return Promise.resolve({ b: 'new-build', f: [] })
      },
    }
  }
  return originalLoad.call(this, request, parent, isMain)
}

global.location = { origin: 'http://localhost:3000' }

const navigationBuildId = require(
  'next/dist/client/navigation-build-id.js',
)
navigationBuildId.setNavigationBuildId('old-build')

global.fetch = async () =>
  new Response(new ReadableStream(), {
    headers: {
      'content-type': 'text/x-component',
      'x-nextjs-deployment-id': 'new-build',
    },
  })

const { fetchServerResponse } = require(
  'next/dist/client/components/router-reducer/fetch-server-response.js',
)

const result = await fetchServerResponse(
  new URL('http://localhost:3000/target'),
  { flightRouterState: ['', {}], nextUrl: null },
)

console.log({ decodeStarted, result })
}

main()
```

With Next 16.2.6 this prints:

```text
{
  decodeStarted: true,
  result: "http://localhost:3000/target"
}
```

Next eventually chooses the correct hard-navigation fallback, but only after
the mismatched Flight response has already entered React's decoder.

### Next.js version

16.2.6. The same ordering is present on
`16.3.0-canary.96` at commit
`779fbad904a96c961b5fca63d2f7e1acff54e0b8`.

